<?php
require_once __DIR__ . '/shared/config.php';
if (logged_in()) { header('Location: ' . dashboard_url()); exit; }
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $username = trim($_POST['username'] ?? ''); $password = $_POST['password'] ?? '';
    $stmt = db()->prepare('SELECT * FROM users WHERE username = ? AND status = 1 LIMIT 1'); $stmt->execute([$username]); $user = $stmt->fetch();
    if ($user && password_verify($password, $user['password'])) { unset($user['password']); $_SESSION['user'] = $user; header('Location: ' . dashboard_url()); exit; }
    $error = 'Incorrect username or password.';
}
?>
